namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications = new();
    private int _nextId = 1;
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the app!"),
            CreateNotification("Your profile was updated."),
            CreateNotification("You have a new follower."),
        });
    }

    /// <summary>Returns all notifications available at the time of the call.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns only notifications with Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > sinceId).ToList();
        }
    }

    /// <summary>Simulates an external system pushing a new notification at random intervals.</summary>
    public void SimulateIncoming()
    {
        string[] samples =
        [
            "New comment on your post.",
            "Someone liked your photo.",
            "System maintenance scheduled.",
            "Your order has shipped!",
            "Meeting reminder: standup in 10 min.",
            "Password change detected.",
        ];

        lock (_lock)
        {
            var msg = samples[Random.Shared.Next(samples.Length)];
            _notifications.Add(CreateNotification(msg));
        }
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@using NotificationsApp.Services
@inject NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications.OrderByDescending(x => x.Id))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private int _latestId;
    private CancellationTokenSource? _cts;

    // Runs during both prerender AND interactive activation.
    // On prerender it populates the list so the HTML is complete.
    // On interactive activation the list is already populated from prerender
    // (Blazor preserves component state across the prerender → interactive handoff),
    // so we just record the high-water mark and skip re-fetching.
    protected override void OnInitialized()
    {
        _notifications = NotificationSvc.GetAll();
        _latestId = _notifications.Count > 0
            ? _notifications.Max(n => n.Id)
            : 0;
    }

    // Called only once the component is truly interactive (not during prerender).
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(5));

        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                // Simulate an external notification arriving.
                NotificationSvc.SimulateIncoming();

                var newer = NotificationSvc.GetSince(_latestId);
                if (newer.Count > 0)
                {
                    _notifications.AddRange(newer);
                    _latestId = newer.Max(n => n.Id);

                    await InvokeAsync(StateHasChanged);
                }
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on disposal — nothing to do.
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

